public class SafeDatabaseExample {

    public static void main(String[] args) {
        try {
            // Conectando ao banco de dados
            Connection connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "root", "password");

            // Obtendo a entrada do usuário diretamente da variável main
            String userInput = System.in.readLine();

            // Preparando a consulta SQL com a entrada do usuário usando StatementParametized
            PreparedStatement preparedStatement = connection.prepareStatement("SELECT * FROM users WHERE name = ?");
            preparedStatement.setString(1, userInput);

            // Executando a consulta
            ResultSet resultSet = preparedStatement.executeQuery();

            // Processando o ResultSet
            while (resultSet.next()) {
                System.out.println("Nome: " + resultSet.getString("name"));
                System.out.println("Email: " + resultSet.getString("email"));
            }

            // Fechando recursos
            resultSet.close();
            preparedStatement.close();
            connection.close();
        } catch (SQLException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
